#!/usr/bin/env python3
"""Generate the Unicode line break classes that text wrapping reads.

Fetches ``LineBreak.txt`` of ``UNICODE_VERSION`` from the Unicode Character
Database and writes the classes in ``CLASSES`` as code point ranges. Python's
``unicodedata`` does not carry this property. The Unicode licence is written
next to the other third-party licences.

To follow a new Unicode version, change ``UNICODE_VERSION`` and run:

    python scripts/vendor/unicode/generate_line_break_data.py
"""

from __future__ import annotations

import sys
import urllib.request
from pathlib import Path

UNICODE_VERSION = "18.0.0"
# The classes src/nuiitivet/widgets/text.py reads.
CLASSES = (
    "BA", "BB", "CJ", "CL", "CP", "EM", "EX", "GL", "HH", "HY", "IN", "IS",
    "JT", "JV", "NS", "OP", "PO", "PR", "QU", "SY", "WJ", "ZWJ",
)  # fmt: skip

DATA_URL = f"https://www.unicode.org/Public/{UNICODE_VERSION}/ucd/LineBreak.txt"
LICENSE_URL = "https://www.unicode.org/license.txt"

ROOT = Path(__file__).resolve().parents[3]
DATA_OUT = ROOT / "src" / "nuiitivet" / "widgets" / "_line_break_data.py"
LICENSE_OUT = ROOT / "LICENSES" / "unicode-LICENSE.txt"

MAX_LINE = 120


def fetch(url: str) -> str:
    """Return the text at ``url``."""
    with urllib.request.urlopen(url) as response:
        return response.read().decode("utf-8")


def parse_ranges(text: str) -> dict[str, list[tuple[int, int]]]:
    """Return the code point ranges of each class in ``CLASSES``, merged and sorted."""
    points: dict[str, list[int]] = {name: [] for name in CLASSES}
    for line in text.splitlines():
        line = line.split("#")[0].strip()
        if not line:
            continue
        span, name = (part.strip() for part in line.split(";"))
        if name not in points:
            continue
        low, _, high = span.partition("..")
        points[name].extend(range(int(low, 16), int(high or low, 16) + 1))

    ranges: dict[str, list[tuple[int, int]]] = {}
    for name, codes in points.items():
        if not codes:
            raise ValueError(f"LineBreak.txt of Unicode {UNICODE_VERSION} has no class {name}")
        merged: list[tuple[int, int]] = []
        for code in sorted(codes):
            if merged and merged[-1][1] == code - 1:
                merged[-1] = (merged[-1][0], code)
            else:
                merged.append((code, code))
        ranges[name] = merged
    return ranges


def render(ranges: dict[str, list[tuple[int, int]]]) -> str:
    """Return the source of the generated module."""
    lines = [
        '"""Unicode line break classes of the characters that hold a line together.',
        "",
        "Generated by scripts/vendor/unicode/generate_line_break_data.py from",
        f"LineBreak.txt of Unicode {UNICODE_VERSION}. Do not edit by hand.",
        '"""',
        "",
        f'UNICODE_VERSION = "{UNICODE_VERSION}"',
        "",
        "# Line_Break class -> inclusive code point ranges.",
        "LINE_BREAK_RANGES: dict[str, tuple[tuple[int, int], ...]] = {",
    ]
    for name in CLASSES:
        lines.append(f'    "{name}": (')
        row = "       "
        for low, high in ranges[name]:
            item = f" (0x{low:04X}, 0x{high:04X}),"
            if len(row) + len(item) > MAX_LINE:
                lines.append(row)
                row = "       "
            row += item
        lines.append(row)
        lines.append("    ),")
    lines.append("}")
    return "\n".join(lines) + "\n"


def main() -> int:
    ranges = parse_ranges(fetch(DATA_URL))
    DATA_OUT.write_text(render(ranges), encoding="utf-8")
    print(f"Wrote {sum(len(r) for r in ranges.values())} ranges of {len(ranges)} classes to {DATA_OUT}")
    LICENSE_OUT.write_text(fetch(LICENSE_URL), encoding="utf-8")
    print(f"Wrote {LICENSE_OUT}")
    return 0


if __name__ == "__main__":
    sys.exit(main())
